const assert = require('assert');
const React = require('react');
const { renderToStaticMarkup } = require('react-dom/server');
const { Counter } = require('./counter.js');

const markup0 = renderToStaticMarkup(React.createElement(Counter, { count: 0 }));
assert(markup0.includes('Count: 0'), `expected 'Count: 0' in markup, got: ${markup0}`);

const markup5 = renderToStaticMarkup(React.createElement(Counter, { count: 5 }));
assert(markup5.includes('Count: 5'), `expected 'Count: 5' in markup, got: ${markup5}`);

const markup42 = renderToStaticMarkup(React.createElement(Counter, { count: 42 }));
assert(markup42.includes('Count: 42'), `expected 'Count: 42' in markup, got: ${markup42}`);

console.log('PASS');
